/**
 * The web terminal's ANSI music filter against the shared vectors.
 *
 * vectors.json is copied from DEViLBOX (src/lib/import/__tests__/fixtures/
 * ansi-music/vectors.json), generated by DCTelnet's
 * tools/ansimusic_reference.py. Every host (DCTelnet, DEViLBOX, this
 * terminal) checks the same bytes against the same events.
 */
import { describe, it, expect } from 'vitest';
import { AnsiMusicStream, type MusicEvent } from '../../../../../packages/terminal/src/utils/ansi-music';
import vectors from './fixtures/ansi-music/vectors.json';

interface Vector {
  name: string;
  input_hex: string;
  text_hex: string;
  events: MusicEvent[];
}

const TOLERANCE = (vectors as { tolerance_ms: number }).tolerance_ms;
const list = (vectors as { vectors: Vector[] }).vectors;

/** Bytes as the socket delivers them: one latin1 char per byte. */
const fromHex = (hex: string): string =>
  (hex.match(/../g) ?? []).map((b) => String.fromCharCode(parseInt(b, 16))).join('');

function run(chunks: string[]): { text: string; events: MusicEvent[] } {
  const stream = new AnsiMusicStream();
  const events: MusicEvent[] = [];
  const onMusic = (e: MusicEvent[]): string => { events.push(...e); return ''; };
  let text = '';
  for (const c of chunks) text += stream.feed(c, onMusic);
  text += stream.flush(onMusic);
  return { text, events };
}

function expectEvents(got: MusicEvent[], want: MusicEvent[]): void {
  expect(got.length).toBe(want.length);
  got.forEach((e, i) => {
    const w = want[i];
    expect({ hz: e.hz, rest: e.rest }).toEqual({ hz: w.hz, rest: w.rest });
    expect(Math.abs(e.ms - w.ms)).toBeLessThanOrEqual(TOLERANCE);
    expect(Math.abs(e.gate - w.gate)).toBeLessThanOrEqual(TOLERANCE);
  });
}

describe('ANSI music shared vectors', () => {
  it('has the vectors', () => {
    expect(list.length).toBeGreaterThan(30);
  });

  for (const v of list) {
    it(`${v.name}: whole buffer`, () => {
      const { text, events } = run([fromHex(v.input_hex)]);
      expect(text).toBe(fromHex(v.text_hex));
      expectEvents(events, v.events);
    });

    it(`${v.name}: one byte per chunk`, () => {
      const { text, events } = run(fromHex(v.input_hex).split(''));
      expect(text).toBe(fromHex(v.text_hex));
      expectEvents(events, v.events);
    });
  }
});
